"use client";

import { useState } from "react";

const questions = [
  {
      question: "ما المقصود بالذكاء الاصطناعي؟",
          options: [
                "تقنية تجعل الأجهزة تنفذ مهامًا تحتاج إلى ذكاء",
                      "نوع من أنواع الإنترنت",
                            "برنامج للرسم فقط",
                                  "جهاز لتخزين الملفات",
                                      ],
                                          correct: 0,
                                            },
                                              {
                                                  question: "هل يستطيع الذكاء الاصطناعي التعلم من البيانات؟",
                                                      options: ["نعم", "لا"],
                                                          correct: 0,
                                                            },
                                                              {
                                                                  question: "هل يمكن للذكاء الاصطناعي أن يخطئ؟",
                                                                      options: ["نعم، قد يخطئ", "لا، لا يخطئ أبدًا"],
                                                                          correct: 0,
                                                                            },
                                                                            ];

                                                                            export default function QuizPage() {
                                                                              const [current, setCurrent] = useState(0);
                                                                                const [selected, setSelected] = useState(null);
                                                                                  const [score, setScore] = useState(0);
                                                                                    const [finished, setFinished] = useState(false);

                                                                                      const question = questions[current];

                                                                                        function nextQuestion() {
                                                                                            if (selected === null) return;

                                                                                                if (selected === question.correct) {
                                                                                                      setScore((prev) => prev + 1);
                                                                                                          }

                                                                                                              if (current < questions.length - 1) {
                                                                                                                    setCurrent((prev) => prev + 1);
                                                                                                                          setSelected(null);
                                                                                                                              } else {
                                                                                                                                    setFinished(true);
                                                                                                                                        }
                                                                                                                                          }

                                                                                                                                            function restartQuiz() {
                                                                                                                                                setCurrent(0);
                                                                                                                                                    setSelected(null);
                                                                                                                                                        setScore(0);
                                                                                                                                                            setFinished(false);
                                                                                                                                                              }

                                                                                                                                                                if (finished) {
                                                                                                                                                                    const finalScore =
                                                                                                                                                                          score + (selected === question.correct ? 1 : 0);

                                                                                                                                                                              return (
                                                                                                                                                                                    <main style={styles.page}>
                                                                                                                                                                                            <div style={styles.card}>
                                                                                                                                                                                                      <div style={styles.emoji}>🏆</div>
                                                                                                                                                                                                                <h1 style={styles.title}>أحسنت!</h1>

                                                                                                                                                                                                                          <p style={styles.text}>لقد أكملت الاختبار بنجاح</p>

                                                                                                                                                                                                                                    <div style={styles.score}>
                                                                                                                                                                                                                                                نتيجتك
                                                                                                                                                                                                                                                            <strong style={styles.scoreNumber}>
                                                                                                                                                                                                                                                                          {finalScore} / {questions.length}
                                                                                                                                                                                                                                                                                      </strong>
                                                                                                                                                                                                                                                                                                </div>

                                                                                                                                                                                                                                                                                                          <button style={styles.button} onClick={restartQuiz}>
                                                                                                                                                                                                                                                                                                                      🔄 أعد الاختبار
                                                                                                                                                                                                                                                                                                                                </button>

                                                                                                                                                                                                                                                                                                                                          <a href="/" style={styles.home}>
                                                                                                                                                                                                                                                                                                                                                      العودة إلى الصفحة الرئيسية
                                                                                                                                                                                                                                                                                                                                                                </a>
                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                              </main>
                                                                                                                                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                      return (
                                                                                                                                                                                                                                                                                                                                                                                          <main style={styles.page}>
                                                                                                                                                                                                                                                                                                                                                                                                <div style={styles.wrapper}>
                                                                                                                                                                                                                                                                                                                                                                                                        <div style={styles.header}>
                                                                                                                                                                                                                                                                                                                                                                                                                  <span>🧠</span>
                                                                                                                                                                                                                                                                                                                                                                                                                            <h1 style={styles.headerTitle}>
                                                                                                                                                                                                                                                                                                                                                                                                                                        اختبار الذكاء الاصطناعي التجريبي
                                                                                                                                                                                                                                                                                                                                                                                                                                                  </h1>
                                                                                                                                                                                                                                                                                                                                                                                                                                                            <p style={styles.subtitle}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        اختر الإجابة الصحيحة واختبر معلوماتك
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div style={styles.progressText}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            السؤال {current + 1} من {questions.length}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div style={styles.progress}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  style={{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ...styles.progressBar,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              width: `${((current + 1) / questions.length) * 100}%`,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div style={styles.card}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <h2 style={styles.question}>{question.question}</h2>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div style={styles.options}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {question.options.map((option, index) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  key={index}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  onClick={() => setSelected(index)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  style={{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ...styles.option,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ...(selected === index
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ? styles.selectedOption
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              : {}),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {option}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      onClick={nextQuestion}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  disabled={selected === null}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              style={{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ...styles.button,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          opacity: selected === null ? 0.5 : 1,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {current === questions.length - 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ? "عرض النتيجة 🏆"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        : "السؤال التالي ←"}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <a href="/" style={styles.home}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ← العودة للرئيسية
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </a>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </main>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

